import{c as s,Q as e,j as i,m as t}from"./chunks/framework.7r1mYKiJ.js";const k=JSON.parse('{"title":"World Mutation","description":"","frontmatter":{},"headers":[],"relativePath":"features/world-mutation.md","filePath":"features/world-mutation.md"}'),n={name:"features/world-mutation.md"};function r(o,a,l,h,p,c){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="world-mutation" tabindex="-1">World Mutation <a class="header-anchor" href="#world-mutation" aria-label="Permalink to &quot;World Mutation&quot;">​</a></h1><p>Some of AetherUHC&#39;s most exciting gamemodes (like <strong>Big Crack</strong> or <strong>Chunk Apocalypse</strong>) require physically altering millions of blocks across the generated map. Doing this in standard Minecraft would instantly crash the server.</p><p>AetherUHC solves this via its proprietary <strong>Post-Gen Mutation Engine</strong>, a tick-budgeted, memory-safe runner that applies these heavy block operations right after the world has finished pre-generating.</p><h2 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h2><ol><li>Once pre-generation completes, the mutation engine kicks in.</li><li>It calculates which chunks need to be altered (e.g., a massive 15-chunk wide X-shape across the map for Big Crack).</li><li>It asynchronously loads only those chunks into a sliding &quot;warmup window&quot; memory cache using Paper ticket scopes.</li><li>It directly modifies the raw chunk data arrays (bypassing block-physics lag) while monitoring the server&#39;s TPS/MSPT (Milliseconds Per Tick).</li><li>If the server starts lagging, the engine automatically yields and pauses its work until the next tick.</li></ol><h2 id="configuring-the-budget" tabindex="-1">Configuring the Budget <a class="header-anchor" href="#configuring-the-budget" aria-label="Permalink to &quot;Configuring the Budget&quot;">​</a></h2><p>You can tweak how fast mutations apply in your <code>plugins/AetherUHC/worldmanagement.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">WORLD-MUTATION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  BLOCKS-PER-TICK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # The maximum number of blocks modified per tick.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  MAX-MSPT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # The mutation pauses if server tick time exceeds this.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ASYNC-CHUNK-WARMUP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Highly recommended to leave true on 1.20+</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  WARMUP-CHUNKS-AHEAD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">48</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # The chunk cache size.</span></span></code></pre></div><p>If you have a high-end CPU, you can safely increase <code>BLOCKS-PER-TICK</code> to <code>24000</code> or higher to speed up post-gen mutations.</p><h2 id="popular-mutation-scenarios" tabindex="-1">Popular Mutation Scenarios <a class="header-anchor" href="#popular-mutation-scenarios" aria-label="Permalink to &quot;Popular Mutation Scenarios&quot;">​</a></h2><ul><li><strong>Big Crack</strong>: Carves an immense, cross-shaped ravine all the way down to bedrock intersecting at the exact center (0,0) of the map.</li><li><strong>Chunk Apocalypse</strong>: Erases vertical columns of random chunks across the map, creating a dangerous, parkour-like fractured environment.</li><li><strong>Underground Parallel</strong>: Clones a slice of the surface world and mirrors it upside-down near bedrock level, creating a surreal subterranean ceiling.</li><li><strong>Dragon Rush</strong>: Pastes End Portal room schematics across various coordinates on the map.</li></ul>`,11)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
